// Read the varint length from the input Slice
uint32_t len;
if (!GetVarint32(input, &len)) {
  return false;
}

// Check if the input has enough bytes for the data
if (input->size() < len) {
  return false;
}

// Set the result Slice to the data immediately following the varint
*result = Slice(input->data(), len);

// Advance the input Slice to point after the data
input->remove_prefix(len);

return true;

